# area: paramspec_concatenate
# hypothesis: stacking a ParamSpec decorator over a Concatenate decorator must keep the signature after the injected db parameter, so query checks as taking (table: str, limit: int = 10) and the outer wrapper must not expose db.
from collections.abc import Callable
from typing import Concatenate, reveal_type


def logged[**P, R](fn: Callable[P, R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(*args, **kwargs)
    return inner


def with_db[**P, R](fn: Callable[Concatenate[str, P], R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn('db', *args, **kwargs)
    return inner


@logged
@with_db
def query(db: str, table: str, limit: int = 10) -> list[str]:
    return [f'{db}.{table}'] * limit


class Repo:
    @logged
    def find(self, key: str) -> int:
        return len(key)


reveal_type(query)
reveal_type(Repo().find)
print(query('t', limit=1), Repo().find('k'))

try:
    query('t', 1, 2)  # expect-error: too many positional arguments
except TypeError as exc:
    print('runtime:', type(exc).__name__)

try:
    query('t', table=1)  # expect-error: multiple values for table
except TypeError as exc:
    print('runtime:', type(exc).__name__)

try:
    Repo().find(1)  # expect-error: int passed as str
except TypeError as exc:
    print('runtime:', type(exc).__name__)
